{"path": "ranges.mjs", "content": "export function mergeRanges(ranges) {
  if (!Array.isArray(ranges)) {
    throw new TypeError("mergeRanges expects an array of [start, end] pairs");
  }

  const pairs = ranges.map((range, index) => {
    if (!Array.isArray(range) || range.length !== 2) {
      throw new TypeError(`Range at index ${index} must be a [start, end] pair`);
    }
    const [start, end] = range;
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) {
      throw new TypeError(
        `Range at index ${index} must have safe integer bounds`
      );
    }
    if (start > end) {
      throw new TypeError(
        `Range at index ${index} must satisfy start <= end`
      );
    }
    return [start, end];
  });

  if (pairs.length === 0) return [];

  pairs.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const result = [];
  let [currentStart, currentEnd] = pairs[0];

  for (let i = 1; i < pairs.length; i += 1) {
    const [start, end] = pairs[i];
    if (start <= currentEnd + 1) {
      if (end > currentEnd) currentEnd = end;
    } else {
      result.push([currentStart, currentEnd]);
      currentStart = start;
      currentEnd = end;
    }
  }
  result.push([currentStart, currentEnd]);

  return result;
}
